import{F as e,I as t,et as n,n as r}from"./chunks/framework.Bs4wm_X5.js";var i=JSON.parse(`{"title":"Melodic harmonics","description":"Converting harmonic frequencies into temporal patterns","frontmatter":{"title":"Melodic harmonics","description":"Converting harmonic frequencies into temporal patterns","layout":"iframe","date":"2026-06-06T00:00:00.000Z","cover":"harmon.jpg","iframe":"/demo/melodic-harmonics.html","standalone":true},"headers":[],"relativePath":"practice/experiments/melodic-harmonics/index.md","filePath":"practice/experiments/melodic-harmonics/index.md","lastUpdated":1791274499000}`),a={name:`practice/experiments/melodic-harmonics/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="melodic-harmonics" tabindex="-1">Melodic Harmonics <a class="header-anchor" href="#melodic-harmonics" aria-label="Permalink to “Melodic Harmonics”">​</a></h1><blockquote><p>Disassembling the harmonic series in time, space, and color.</p></blockquote><p>An interactive installation that takes the harmonics of a sawtooth wave and <strong>separates them rhythmically</strong> — each harmonic becomes a concentric circle spinning at its own tempo, triggering its pitch as it passes the meridian. What is normally fused into a single timbral moment is unfolded into a polyrhythmic cascade you can see, hear, and understand.</p><hr><h2 id="the-core-idea" tabindex="-1">The Core Idea <a class="header-anchor" href="#the-core-idea" aria-label="Permalink to “The Core Idea”">​</a></h2><p>A sawtooth wave is the sum of all integer harmonics:</p><p>$$f,; 2f,; 3f,; 4f,; 5f,; 6f,; 7f,; 8f,; \\dots$$</p><p>Normally we hear them <strong>simultaneously</strong> — that&#39;s what makes a sawtooth sound like a sawtooth. The ear fuses them into one complex tone and we call it <em>timbre</em>.</p><p>This app <strong>disassembles</strong> them. Each harmonic gets its own circle, its own tempo, its own moment in time. Instead of hearing a single buzz, you hear the intervals emerge one by one:</p><ul><li><strong>1:1</strong> — the tonic, grounding, slow</li><li><strong>2:1</strong> — the octave, familiar, twice as fast</li><li><strong>3:2</strong> — the perfect fifth, appearing as the 3rd harmonic</li><li><strong>5:4</strong> — the major third, the 5th harmonic&#39;s secret</li><li><strong>7:4</strong> — the harmonic seventh, that blue note between minor and major</li><li><strong>8:1</strong> — three octaves up, cycling back to the tonic</li></ul><p>You don&#39;t just <em>learn</em> these ratios. You <strong>feel</strong> them arriving at different speeds, nested inside each other, building the architecture of a single pitch from the inside out.</p><hr><h2 id="the-octave-rule-pitch-is-tempo" tabindex="-1">The Octave Rule: Pitch IS Tempo <a class="header-anchor" href="#the-octave-rule-pitch-is-tempo" aria-label="Permalink to “The Octave Rule: Pitch IS Tempo”">​</a></h2><p>The deepest insight this tool reveals is the <strong>octave rule</strong>:</p><blockquote><p>A frequency of 440 Hz and a tempo of 412.5 BPM are the same phenomenon, separated by octaves.</p></blockquote><p>Every pitch class is also a rhythm class. A4 = 440 Hz. Drop it down six octaves: 440 ÷ 64 = 6.875 Hz = 412.5 BPM. The note <em>is</em> the tempo. The interval <em>is</em> the polyrhythm.</p><p>When you select a pitch class, the app computes two things from the same number:</p><table tabindex="0"><thead><tr><th>Domain</th><th>Calculation</th><th>Example (A)</th></tr></thead><tbody><tr><td><strong>Pitch</strong></td><td>Frequency shifted to bass range (30–60 Hz)</td><td>A₁ ≈ 55 Hz</td></tr><tr><td><strong>Tempo</strong></td><td>Frequency × 60, shifted to ≤ 412.5 BPM</td><td>412.5 BPM → fundamental at ~51 BPM</td></tr></tbody></table><p>The fundamental circle pulses every ~51 BPM (a slow, grounding bass note). The 8th harmonic spins at 412.5 BPM (fast enough to feel rhythmic urgency). All intermediate harmonics fill the space between.</p><p><strong>Pitch octave</strong> and <strong>tempo octave</strong> controls shift these independently by ±2 octaves, letting you explore the same harmonic structure at different registers and speeds.</p><hr><h2 id="what-you-see" tabindex="-1">What You See <a class="header-anchor" href="#what-you-see" aria-label="Permalink to “What You See”">​</a></h2><ul><li><strong>Concentric circles</strong> — outermost is the fundamental (harmonic 1), innermost is the highest harmonic. Each circle&#39;s radius is dynamically computed to fit all harmonics within the same visual space.</li><li><strong>Tick marks</strong> — harmonic <em>n</em> has <em>n</em> marks evenly distributed around its circle. This makes the integer ratio <strong>visible</strong>: the 3rd harmonic has 3 marks, the 5th has 5, the 7th has 7. You can literally <em>count</em> the ratio.</li><li><strong>Colors</strong> — each harmonic is colored by its Chromatone pitch class. The harmonic series naturally visits different notes: the 3rd harmonic is a fifth above the root, the 5th is a major third, the 7th is a flat seventh. The colors reveal this interval structure at a glance.</li><li><strong>Radial grid</strong> — faint sub-pixel lines and circles provide spatial reference without distraction.</li><li><strong>The meridian</strong> — a faint dashed line at 12 o&#39;clock. When a harmonic&#39;s main dot crosses it, the sound triggers.</li></ul><h2 id="what-you-hear" tabindex="-1">What You Hear <a class="header-anchor" href="#what-you-hear" aria-label="Permalink to “What You Hear”">​</a></h2><ul><li><strong>Pure sine waves</strong> at exact integer-ratio frequencies (just intonation, not equal temperament).</li><li><strong>1/n amplitude scaling</strong> — each harmonic is quieter than the last, matching the natural spectral envelope of a sawtooth wave. The fundamental dominates; upper harmonics shimmer.</li><li><strong>Polyrhythmic layering</strong> — at default tempo, the fundamental pulses every ~2 seconds while the 8th harmonic fires ~13 times per second. The space between is filled with 3-against-4-against-5-against-7 patterns.</li><li><strong>Temporal blur</strong> — at higher tempos, fast harmonics stop sounding like individual hits and fuse into a continuous tone. You are literally hearing the transition from rhythm to pitch.</li></ul><hr><h2 id="what-this-reveals" tabindex="-1">What This Reveals <a class="header-anchor" href="#what-this-reveals" aria-label="Permalink to “What This Reveals”">​</a></h2><h3 id="_1-timbre-is-frozen-rhythm" tabindex="-1">1. Timbre is frozen rhythm <a class="header-anchor" href="#_1-timbre-is-frozen-rhythm" aria-label="Permalink to “1. Timbre is frozen rhythm”">​</a></h3><p>When harmonics fire fast enough, they stop being separate events and become a single complex tone. Speed up the tempo octave and watch (listen to) discrete pulses dissolve into timbre. Slow it down and timbre dissolves back into rhythm. There is no boundary — only octaves.</p><h3 id="_2-intervals-are-ratios-made-audible" tabindex="-1">2. Intervals are ratios made audible <a class="header-anchor" href="#_2-intervals-are-ratios-made-audible" aria-label="Permalink to “2. Intervals are ratios made audible”">​</a></h3><p>The 3rd harmonic doesn&#39;t play &quot;a fifth.&quot; It plays the frequency that <em>is</em> 3/2 of the fundamental. In equal temperament we approximate this. Here you hear the <strong>pure</strong> 3:2, the <strong>pure</strong> 5:4, the <strong>pure</strong> 7:4. The difference is subtle but profound — pure intervals have a stillness, a lack of beating, that tempered intervals don&#39;t.</p><h3 id="_3-the-harmonic-series-is-a-color-progression" tabindex="-1">3. The harmonic series is a color progression <a class="header-anchor" href="#_3-the-harmonic-series-is-a-color-progression" aria-label="Permalink to “3. The harmonic series is a color progression”">​</a></h3><p>In Chromatone, A is red, E is azure, C♯ is green, G is magenta. The harmonic series on A visits: <strong>red → red → azure → red → green → azure → magenta → red</strong>. You see the interval structure as a color sequence. The 7th harmonic (magenta, a flat seventh) is the first &quot;surprise&quot; — the note that doesn&#39;t fit the major scale, the blue note hiding inside every pitched sound.</p><h3 id="_4-nested-periodicity-is-the-structure-of-pitch" tabindex="-1">4. Nested periodicity is the structure of pitch <a class="header-anchor" href="#_4-nested-periodicity-is-the-structure-of-pitch" aria-label="Permalink to “4. Nested periodicity is the structure of pitch”">​</a></h3><p>Each harmonic&#39;s period is an exact integer division of the fundamental&#39;s period. The 4th harmonic fires exactly 4 times per fundamental cycle. The 6th fires 6 times. This nesting is not a metaphor — it is the <strong>physical reality</strong> of what makes a pitched sound. The circles make this nesting visible as concentric rotation.</p><h3 id="_5-8-16-32-diminishing-returns-of-timbre" tabindex="-1">5. 8, 16, 32: diminishing returns of timbre <a class="header-anchor" href="#_5-8-16-32-diminishing-returns-of-timbre" aria-label="Permalink to “5. 8, 16, 32: diminishing returns of timbre”">​</a></h3><p>Switch to 32 harmonics. The outer 8 circles dominate your perception. The inner 24 add brightness and edge but the fundamental structure is already established by the first few harmonics. This is why a clarinet (odd harmonics only) sounds different from a sawtooth (all harmonics) — and why you can hear the difference by toggling the count.</p><hr><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to “Controls”">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Options</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Pitch</strong></td><td>A – G♯ (12 buttons)</td><td>Sets the root pitch class and its Chromatone color</td></tr><tr><td><strong>Pitch Octave</strong></td><td>−2 to +2</td><td>Shifts the fundamental frequency by octaves</td></tr><tr><td><strong>Tempo Octave</strong></td><td>−2 to +2</td><td>Shifts the fundamental tempo by octaves</td></tr><tr><td><strong>Harmonics</strong></td><td>8 / 16 / 32</td><td>Number of harmonics in the series</td></tr></tbody></table><p>Default state: <strong>A</strong>, pitch octave <strong>+1</strong>, tempo octave <strong>−1</strong>, <strong>8</strong> harmonics.</p><hr><h2 id="suggested-explorations" tabindex="-1">Suggested Explorations <a class="header-anchor" href="#suggested-explorations" aria-label="Permalink to “Suggested Explorations”">​</a></h2><ol><li><p><strong>Start with A, 8 harmonics, defaults.</strong> Listen to the fundamental pulse. Count the marks on each circle. Hear how the 3rd harmonic (azure) arrives between fundamental beats.</p></li><li><p><strong>Switch to C.</strong> The color progression changes: lime → lime → magenta → lime → azure → magenta → orange → lime. The 7th harmonic is now B♭ (orange) — a whole step below the tonic.</p></li><li><p><strong>Set harmonics to 32.</strong> The inner circles spin fast. Listen to how the texture thickens. The outer 8 circles still anchor the rhythm.</p></li><li><p><strong>Drop tempo octave to −2.</strong> Everything slows dramatically. You can now hear each harmonic as a distinct event. The polyrhythm becomes a meditation.</p></li><li><p><strong>Raise tempo octave to +2.</strong> The inner harmonics blur into continuous tone. You are hearing the birth of timbre from rhythm.</p></li><li><p><strong>Compare 8 vs 16 vs 32 harmonics at the same tempo.</strong> Notice how the &quot;color&quot; of the sound changes — more harmonics means brighter, more complex timbre. Fewer means purer, more fundamental.</p></li><li><p><strong>Try pitch octave −1.</strong> The fundamental drops below 30 Hz. You may feel it more than hear it. The harmonics are now in the audible bass range. The interval relationships become physical vibrations in your body.</p></li></ol><hr><h2 id="technical-notes" tabindex="-1">Technical Notes <a class="header-anchor" href="#technical-notes" aria-label="Permalink to “Technical Notes”">​</a></h2><ul><li><strong>Self-contained</strong> — single HTML file, no dependencies, no build step.</li><li><strong>Web Audio API</strong> — oscillators scheduled with sample-accurate timing via lookahead scheduler.</li><li><strong>Just intonation</strong> — frequencies are exact integer multiples of the fundamental (<code>n × f₁</code>), not equal-tempered approximations.</li><li><strong>Chromatone color mapping</strong> — each harmonic&#39;s interval in cents (<code>1200 × log₂(n)</code>) is mapped to the nearest 12-TET pitch class, then to its Chromatone color.</li><li><strong>Pre-allocated typed arrays</strong> — all audio and animation buffers are allocated once at startup for zero GC pressure during playback.</li><li><strong>SVG rendering</strong> — all 32 harmonic groups are pre-created and toggled via display. Radii are recalculated dynamically when the harmonic count changes.</li></ul>`,47)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};